"""Authored synthetic fixtures; no private user documents."""
from pathlib import Path
import zipfile
from reportlab.pdfgen import canvas
from reportlab.lib.pdfencrypt import StandardEncryption
root=Path(__file__).resolve().parents[1]/'testdata/formats';root.mkdir(parents=True,exist_ok=True)
paragraphs=['Alice was curious about the quiet garden. She carried a book and a small notebook.','The door opened quickly. A gentle breeze moved the leaves, and the city sounded far away.']
(root/'sample.txt').write_text('\n\n'.join(paragraphs),encoding='utf8')
(root/'unicode.txt').write_text('Любопытный читатель — English curious.\n\nВторая строка.',encoding='utf-16')
fb2='<?xml version="1.0" encoding="utf-8"?><FictionBook xmlns="http://www.gribuser.ru/xml/fictionbook/2.0"><description><title-info><author><first-name>QA</first-name><last-name>Writer</last-name></author><book-title>Format sample</book-title><lang>en</lang></title-info></description><body><section><title><p>A quiet garden</p></title>'+''.join('<p>'+p+'</p>' for p in paragraphs)+'</section></body></FictionBook>'
(root/'sample.fb2').write_text(fb2,encoding='utf8')
with zipfile.ZipFile(root/'sample.fb2.zip','w',zipfile.ZIP_DEFLATED) as z:z.writestr('book.fb2',fb2)
with zipfile.ZipFile(root/'sample.docx','w',zipfile.ZIP_DEFLATED) as z:
    z.writestr('[Content_Types].xml','<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="xml" ContentType="application/xml"/></Types>')
    z.writestr('word/document.xml','<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+''.join('<w:p><w:r><w:t>'+p+'</w:t></w:r></w:p>' for p in paragraphs)+'<w:tbl><w:tr><w:tc><w:p><w:r><w:t>Table cell content.</w:t></w:r></w:p></w:tc></w:tr></w:tbl></w:body></w:document>')
    z.writestr('docProps/core.xml','<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:title>Format sample</dc:title><dc:creator>QA Writer</dc:creator></cp:coreProperties>')
for name,encryption in [('sample.pdf',None),('password.pdf',StandardEncryption('secret',canCopy=0))]:
    c=canvas.Canvas(str(root/name),encrypt=encryption,invariant=1);c.setTitle('Format sample');c.setAuthor('QA Writer')
    for i in range(2):
        c.setFont('Helvetica',12);c.drawString(50,780,paragraphs[0]);c.drawString(50,755,paragraphs[1]);c.showPage()
    c.save()
c=canvas.Canvas(str(root/'scan.pdf'),invariant=1);c.rect(50,50,200,200);c.save()
(root/'xxe.fb2').write_text('<?xml version="1.0"?><!DOCTYPE FictionBook [<!ENTITY e SYSTEM "file:///not-readable">]><FictionBook><body><section><p>&e;</p></section></body></FictionBook>',encoding='utf8')
(root/'broken.docx').write_bytes(b'not a ZIP')
(root/'README.md').write_text('# Import fixtures\n\nSynthetic QA text, generated by tools/create_format_fixtures.py. Text-layer, scanned/empty and password-protected PDF; DOCX, FB2, ZIP, TXT, malformed/XXE samples. No private documents.\n',encoding='utf8')
print(root)
